import type { Verse } from '../types/verse';
import { BIBLE_BOOKS, referenceBookName } from './bibleBooks';
import { CURATED_VERSES } from './curatedVerses';
import { FALLBACK_TRANSLATION, translationInfo, type Translation } from './translations';
// Generated by scripts/build-bible.ts: { [translation]: { [verseId]: text } }.
// A translation lacks a verse it can't supply (Old Testament or lost text in Amharic).
import curatedText from './curatedText.json';

const TEXT = curatedText as Record<Translation, Record<string, string | undefined>>;

/**
 * The built-in library, worded in the given translation. A verse that
 * translation doesn't have is shown in FALLBACK_TRANSLATION, and labelled so.
 */
export function curatedVerses(translation: Translation): Verse[] {
  return CURATED_VERSES.map((cv) => {
    const book = BIBLE_BOOKS.find((b) => b.code === cv.book)!;
    const own = TEXT[translation][cv.id];
    const used = own ? translation : FALLBACK_TRANSLATION;
    const language = translationInfo(used).language;
    return {
      id: cv.id,
      reference: `${referenceBookName(book, language)} ${cv.chapter}:${cv.verses}`,
      book: book.name,
      chapter: cv.chapter,
      verseNum: cv.verses,
      text: own ?? TEXT[FALLBACK_TRANSLATION][cv.id]!,
      category: cv.category,
      translation: used,
      tags: cv.tags,
    };
  });
}

export const FIRST_VERSE_ID = CURATED_VERSES[0].id;
